SELECT p.id AS position_id, s.id, s.interval_code, s.candle_open_time, s.generated_at, s.decision, s.original_decision, s.total_score, s.data_quality_valid FROM paper_position p JOIN trade_signal s ON s.id = (SELECT s2.id FROM trade_signal s2 WHERE s2.symbol = p.symbol AND s2.interval_code = '5m' AND s2.generated_at <= p.opened_at ORDER BY s2.generated_at DESC LIMIT 1) OR s.id = (SELECT s3.id FROM trade_signal s3 WHERE s3.symbol = p.symbol AND s3.interval_code = '1h' AND s3.generated_at <= p.opened_at ORDER BY s3.generated_at DESC LIMIT 1) WHERE p.id IN (182,172,162,158,143,137) ORDER BY p.id, s.interval_code